% % 单峰Voigt函数拟合气体吸收光谱
% % 功能：使用单个峰的位置、高度和半高全宽（FWHM）作为初始参数进行拟合
% 
% % clear; clc; close all;
% 
% %% 1. 数据准备
% % 替换为你的实际光谱数据（x：波数/波长，y：吸光度）
% x = linspace(980, 1020, 500);  % 波数范围
% % 模拟单峰光谱数据
% y_true = 0.7*voigt(x, 1000, 2.5, 0.6) + ...  % 单峰Voigt曲线
%          0.0003*x + 0.08 + ...                % 线性基线
%          0.008*randn(size(x));                % 噪声
% y = y_true;


x=v;y=alp
%% 2. 设置初始参数（仅需单峰的三个参数）
% 格式：[峰位置, 峰高度, 半高全宽(FWHM)]
peak_params = [18.55, 0.05 3, 6];  % 根据实际光谱调整这些值

% 解析单峰参数
v0_init = peak_params(1);    % 初始峰位置
A_init = peak_params(2);     % 初始峰高度
fwhm_init = peak_params(3);  % 初始半高全宽

% 将FWHM分解为高斯和洛伦兹展宽（初始估计）
% 初始分配比例：高斯50%，洛伦兹50%
fwhm_gauss_init = 0.5 * fwhm_init;
fwhm_lorentz_init = 0.5 * fwhm_init;

% 转换为Voigt函数所需参数
sigma_init = fwhm_gauss_init / (2*sqrt(2*log(2)));  % 高斯展宽参数
gamma_init = fwhm_lorentz_init / 2;                 % 洛伦兹展宽参数

% 完整合参数向量：[峰位置, 振幅, sigma, gamma, 基线a, 基线b]
p0 = [v0_init, A_init, sigma_init, gamma_init, 0.0001, 0.05];

%% 3. 设置参数边界（确保证物理合理性）
lb = [v0_init-3, 0.3*A_init, 0.1, 0.01, -0.001, -0.1];  % 下限
ub = [v0_init+3, 1.5*A_init, 5, 3, 0.001, 0.3];         % 上限

%% 4. 执行拟合
% 定义模型包装函数
model_fun_wrapper = @(params, x_data) model_fun(params, x_data);

% 设置优化选项
if exist('optimoptions', 'builtin')
    options = optimoptions('lsqcurvefit', ...
        'Display', 'iter', ...
        'MaxIterations', 1000);
else
    options = optimset(...
        'Display', 'iter', ...
        'MaxIter', 1000);
end

% 执行拟合
[p_opt, resnorm] = lsqcurvefit(model_fun_wrapper, p0, x, y, lb, ub, options);

%% 5. 计算拟合结果
y_fit = model_fun(p_opt, x);  % 拟合曲线
residual = y - y_fit;         % 残差

%% 6. 结果可视化
% figure('Position', [100, 100, 800, 600]);

figure('Position');

% 原始数据与拟合曲线
subplot(2,1,1);
plot(x, y, 'b', 'LineWidth', 1.2, 'DisplayName', '原始光谱');
hold on;
plot(x, y_fit, 'r--', 'LineWidth', 1.5, 'DisplayName', 'Voigt拟合');
xlabel('波数 (cm^{-1})');
ylabel('吸光度');
title('单峰Voigt拟合结果');
legend('Location', 'best');
grid on;

% 残差图
subplot(2,1,2);
plot(x, residual, 'g', 'LineWidth', 1);
xlabel('波数 (cm^{-1})');
ylabel('残差');
title('拟合残差');
grid on;

%% 7. 输出拟合参数
v0 = p_opt(1);
A = p_opt(2);
sigma = p_opt(3);
gamma = p_opt(4);

% 计算各展宽的FWHM
fwhm_gauss = 2*sigma*sqrt(2*log(2));  % 高斯半高全宽
fwhm_lorentz = 2*gamma;               % 洛伦兹半高全宽
% 经验公式计算Voigt半高全宽
fwhm_voigt = 0.5346*fwhm_lorentz + sqrt(0.2166*fwhm_lorentz^2 + fwhm_gauss^2);

disp('拟合参数结果：');
fprintf('峰位 v0: %.2f\n', v0);
fprintf('峰高 A: %.3f\n', A);
fprintf('高斯展宽 FWHM: %.3f\n', fwhm_gauss);
fprintf('洛伦兹展宽 FWHM: %.3f\n', fwhm_lorentz);
fprintf('Voigt总FWHM: %.3f\n\n', fwhm_voigt);
fprintf('基线参数 (y = a*x + b)：\n');
fprintf('  a: %.6f,  b: %.3f\n', p_opt(5), p_opt(6));

%% 以下是函数定义
% 1. Voigt函数（数值积分实现）
function v = voigt(x, v0, sigma, gamma)
    v = zeros(size(x));
    sqrt2 = sqrt(2);
    a = gamma / (sigma * sqrt2);  % 洛伦兹与高斯展宽比
    
    for i = 1:length(x)
        x_norm = (x(i) - v0) / (sigma * sqrt2);  % 归一化频率
        
        % 数值积分计算Voigt函数
        fun = @(t) exp(-t.^2) ./ (a^2 + (x_norm - t).^2);
        integral_val = integral(fun, -Inf, Inf);
        
        % 计算Voigt函数值
        v(i) = (a / sqrt(pi)) * integral_val;
    end
end

% 2. 单峰拟合模型（Voigt + 线性基线）
function y_model = model_fun(params, x)
    % 解析参数
    v0 = params(1);       % 峰位
    A = params(2);        % 振幅（峰高）
    sigma = params(3);    % 高斯展宽
    gamma = params(4);    % 洛伦兹展宽
    a = params(5);        % 基线斜率
    b = params(6);        % 基线截距
    
    % 单峰Voigt + 基线
    y_model = A * voigt(x, v0, sigma, gamma) + a*x + b;
end
